    out = llm.invoke([
        SystemMessage(content=SYSTEM_PROMPT),
        HumanMessage(content=f"<rider_text>\n{text[:3000]}\n</rider_text>{repair_note}"),
    ])
    content = out.content
    if isinstance(content, list):
        content = " ".join(str(p) for p in content)
    return content or ""


def _strip_json(reply: str) -> str:
    reply = reply.strip()
    fence = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", reply, re.DOTALL)
    if fence:
        return fence.group(1)
    brace = re.search(r"\{.*\}", reply, re.DOTALL)
    return brace.group(0) if brace else reply


def _validate(parsed: dict, text: str, received_at_ist: datetime.date) -> dict:
    if not isinstance(parsed, dict):
        raise TypeError("not a JSON object")
    kind = parsed.get("kind")
    if kind not in KINDS:
        raise ValueError(f"kind {kind!r} unsupported")
    trip_ids = parsed.get("trip_ids", [])
    if not isinstance(trip_ids, list) or any(not isinstance(x, str) for x in trip_ids):
        raise ValueError("trip_ids must be a list of strings")
    trips = [t.upper() for t in trip_ids if re.fullmatch(r"t\d{4,8}", t.strip(), re.IGNORECASE)]
    days_raw = parsed.get("days", [])
    if not isinstance(days_raw, list):
        days_raw = []
    days = []
    for d in days_raw:
        try:
            days.append(datetime.date.fromisoformat(str(d)[:10]).isoformat())
        except (ValueError, TypeError):
            continue
    claimed = parsed.get("claimed_amount")
    if claimed is not None:
        try:
            claimed_i = int(claimed)
            claimed = claimed_i if 0 < claimed_i <= 100000 else None
        except (TypeError, ValueError):
            claimed = None
    return {
        "kind": kind if kind in KINDS else infer_kind_blind(text),
        "trip_ids": trips or normalize_trip_ids(text),
        "days": days or [d.isoformat() for d in normalize_dates(text, received_at_ist)],
        "claimed_amount": claimed,
        "self_rider_mention": parsed.get("self_rider_mention") or None,
        "injection": bool(parsed.get("injection")),
        "tone_flag": parsed.get("tone_flag") if parsed.get("tone_flag") in
                     ("abuse", "legal_media", "threat") else None,
        "asks_human": bool(parsed.get("asks_human")),
    }


def claim_regex(text: str) -> int | None:
    for group in CLAIM_RE.findall(text):
        for g in group:
            if g and g.isdigit():
                val = int(g)
                if 1 <= val <= 100000:
                    return val
    return None


def infer_kind_blind(text: str) -> str:
    t = text.lower()
    if "incentive" in t or "bonous" in t or "bonus" in t:
        return "incentive"
    if "penalty" in t or "penalti" in t or "cancel" in t:
        return "penalty"
    if "surge" in t:
        return "surge"
    return "short_pay_day"


def tone_regex(text: str) -> str | None:
    t = text.lower()
    if re.search(r"\b(lawyer|legal|media|news|court|consumer forum)\b", t):
        return "legal_media"
    if re.search(r"\b(idiot|stupid|abuse|gali|bakchod)\b", t):
        return "abuse"
    return None


def asks_human_regex(text: str) -> bool:
    return bool(re.search(r"\b(direct baat|insaan|human|manager|supervisor|team se baat)\b",
                          text.lower()))

"""FastAPI service: fixed contracts POST /messages, GET /trace, GET /ops/pending, GET /health."""

from __future__ import annotations

import uuid
from contextlib import asynccontextmanager
from datetime import datetime

import psycopg
from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field

from app import db
from app.config import settings
from app.data_loader import DATA_DIR


class IncomingMessage(BaseModel):
    message_id: str = Field(min_length=1, max_length=256)
    rider_id: str = Field(min_length=1, max_length=32)
    text: str = Field(min_length=1, max_length=10_000)
    received_at: str = Field(min_length=1)


@asynccontextmanager
async def lifespan(app: FastAPI):
    conn = db.connect(settings.database_url)
    db.run_migrations(conn)
    loaded = db.seed(conn, DATA_DIR)
    recovery = _recover_stuck_payments(conn)
    conn.close()
    app.state.initialized = loaded
    app.state.payment_recovery = recovery
    yield
    conn.close()


def _recover_stuck_payments(conn) -> list[dict]:
    """Startup invariant: paySwift may have committed a write whose answer we never
    saw. Resolve every stuck `sent` payment by reconciling the provider ledger
    before any retry is ever attempted."""
    from app.payments import reconcile_stuck_sent
    from app.payswift import PaySwiftClient

    try:
        return reconcile_stuck_sent(conn, PaySwiftClient())
    except Exception as exc:  # Payswift down at boot must NOT block the service
        db.trace(conn, "*", "warning", "payment_recovery", {"error": str(exc)[:300]}, None)
        return []


app = FastAPI(title="QuickDrop Rider Payout Dispute Desk", lifespan=lifespan)


def get_conn() -> psycopg.Connection:
    if not hasattr(app.state, "conn"):
        app.state.conn = db.connect(settings.database_url)
    return app.state.conn


@app.get("/health")
def health():
    try:
        conn = get_conn()
        ready = db.is_ready(conn, app.state.initialized)
    except Exception:
        raise HTTPException(status_code=503, detail="database not ready") from None
    if not ready:
        raise HTTPException(status_code=503, detail="migrations/seeding pending")
    return {"status": "ok"}


@app.post("/messages")
def messages(msg: IncomingMessage, request: Request):
    """Idempotency contract:
    - First delivery: process, store reply, trace.
    - Duplicate (same message_id): return stored reply; no new side effects.
    - Duplicate racing the first: wait briefly, else deterministic fallback.
    """
    try:
        received_at = _parse_received_at(msg.received_at)
    except ValueError:
        raise HTTPException(status_code=400, detail="received_at not ISO-8601") from None

    conn = get_conn()
    claimed = _claim_inbound(conn, msg, received_at)
    if claimed == "exists":
        stored = conn.execute(
            "SELECT * FROM inbound_messages WHERE message_id = %s", (msg.message_id,)
        ).fetchone()
        if stored is None:
            return JSONResponse(status_code=200, content={"reply": _fallback_safe()})
        waited = _wait_for_reply(conn, msg.message_id)
        if waited:
            return {"reply": waited}
        return JSONResponse(status_code=200, content={"reply": _fallback_safe()})

    try:
        reply = _process_message(conn, msg, received_at)
    except Exception as exc:  # never 5xx: fail safe, escalate visible via ops page
        conn.execute(
            "UPDATE inbound_messages SET ok = false, error = %s,"
            "reply = %s, reply_at = now() WHERE message_id = %s",
            (str(exc)[:500], _fallback_safe(), msg.message_id),
        )
        _record_ops_failure(conn, msg.rider_id, str(exc))
        db.trace(
            conn,
            msg.rider_id,
            "error",
            "process_message",
            {"message_id": msg.message_id},
            {"error": str(exc)[:500]},
        )
        reply = _fallback_safe()
    return {"reply": reply}


def _claim_inbound(conn, msg: IncomingMessage, received_at: datetime) -> str:
    cur = conn.execute(
        "INSERT INTO inbound_messages (message_id, rider_id, text, received_at) "
        "VALUES (%s,%s,%s,%s) ON CONFLICT (message_id) DO NOTHING",
        (msg.message_id, msg.rider_id, msg.text, received_at),
    )
    return "claimed" if cur.rowcount else "exists"


def _wait_for_reply(conn, message_id: str, timeout_s: float = 8.0) -> str | None:
    import time

    deadline = time.monotonic() + timeout_s
    while time.monotonic() < deadline:
        time.sleep(0.05)
        row = conn.execute(
            "SELECT reply, error, ok FROM inbound_messages WHERE message_id = %s", (message_id,)
        ).fetchone()
        if row and (row["reply"] is not None or row["ok"] is False):
            return row["reply"] if row["reply"] else _fallback_safe()
    return None


def _fallback_safe() -> str:
    return (
        "Aapki baat hum team tak pahuncha di hai. Punyarika/technical problem ke karan "
        "abhi confirm nahi kar pa rahe; humari ops team jald aapka case dekhegi."
    )


def _record_ops_failure(conn, rider_id: str, reason: str) -> None:
    conn.execute(
        "INSERT INTO ops_items (id, rider_id, type, amount, reason) VALUES (%s,%s,%s,%s,%s)"
        "ON CONFLICT (id) DO NOTHING",
        (str(uuid.uuid4()), rider_id, "escalation", None, f"processing failure: {reason}"),
    )


def _process_message(conn, msg: IncomingMessage, received_at: datetime) -> str:
    """Phase-1 stub: deterministic acknowledgement; agent core arrives in Phase 3."""
    db.trace(
        conn,
        msg.rider_id,
        "message_in",
        "inbound_message",
        {"message_id": msg.message_id, "text": msg.text, "received_at": msg.received_at},
        None,
    )
    reply = (
        "Aapka message mil gaya (Phase 1 stub). "
        f"Ref: {msg.message_id} @ {received_at.isoformat()}"
    )
    db.trace(conn, msg.rider_id, "reply", "stub_reply", None, reply)
    conn.execute(
        "UPDATE inbound_messages SET reply = %s, reply_at = now(), ok = true "
        "WHERE message_id = %s",
        (reply, msg.message_id),
    )
    return reply


def _parse_received_at(value: str) -> datetime:
    from app.policy import parse_received_at

    return parse_received_at(value)


@app.get("/trace/{rider_id}")
def trace_for(rider_id: str):
    conn = get_conn()
    steps = conn.execute(
        "SELECT at, type, name, input, output "
        "FROM trace_steps WHERE rider_id = %s ORDER BY step_id",
        (rider_id,),
    ).fetchall()
    return [
        {
            "at": s["at"].isoformat(),
            "type": s["type"],
            "name": s["name"],
            "input": s["input"],
            "output": s["output"],
        }
        for s in steps
    ]


@app.get("/ops/pending")
def ops_pending():
    conn = get_conn()
    rows = conn.execute(
        "SELECT id, rider_id, type, amount, reason, created_at "
        "FROM ops_items WHERE status = 'pending' ORDER BY created_at",
    ).fetchall()
    return [
        {
            "id": r["id"],
            "rider_id": r["rider_id"],
            "type": r["type"],
            "amount": r["amount"],
            "reason": r["reason"],
            "created_at": r["created_at"].isoformat(),
        }
        for r in rows
    ]

