"""Conversation flow: one rider message -> verified outcome + reply (deterministic).

Stage functions double as LangGraph nodes; the LLM only parses text, and its
output is validated/ignored. Money decisions come from claims.py + payments.py.
"""

from __future__ import annotations

import datetime
import hashlib
import json
import re
import uuid
from decimal import Decimal

from app.config import settings
from app.db import trace
from app.payswift import PaySwiftClient, idempotency_key

from . import extraction, issues, replies, tools

_INJECT_RE = re.compile(r"ignore (all )?(previous|prior) (rules|instructions|prompts)", re.IGNORECASE)


def handle_message(conn, rider_id: str, message_id: str, text: str, received_at: str) -> str:
    """One full turn; called by main after the idempotency claim."""
    received_day = tools.received_day_of(received_at)
    convo = issues.current_conversation(conn, rider_id, received_day)

    # ---- stage: triage (LLM bounded; regex fallback) ----
    try:
        triage = extraction.extract_triage(text, received_day)
    except Exception as exc:  # noqa: BLE001 provider failure must never 5xx
        triage = extraction.fallback_triage(text, received_day)
        trace(conn, rider_id, "error", "extraction", {"message_id": message_id},
              {"error": str(exc)[:300], "fallback": True})
    trace(conn, rider_id, "decision", "extract_entities",
          {"message_id": message_id}, {"triage": _clean(triage)})

    # ---- stage: safety overrides ----
    if triage.get("self_rider_mention") and triage["self_rider_mention"] != rider_id:
        return _finish(conn, rider_id, message_id, replies.identity_bound(),
                       "ESCALATE", "rider named another rider id")
    injected = triage.get("injection") or bool(_INJECT_RE.search(text))
    if injected or triage.get("tone_flag") == "threat":
        ops_id = _record_ops(conn, rider_id, "escalation", None,
                             f"{message_id}: {'injection attempt' if injected else 'threat'}")
        trace(conn, rider_id, "decision", "safety_block", {"message_id": message_id},
              {"outcome": "ESCALATE", "ops_id": ops_id})
        return _finish(conn, rider_id, message_id, replies.escalation("safety"),
                       "ESCALATE", "threat or injection")

    open_conv_issues = issues.open_issues(conn, rider_id, convo["conversation_id"])

    # ---- stage: intent (new complaint vs continuation/pushback) ----
    referencing = bool(triage["trip_ids"]) or bool(triage["days"]) \
        or triage["kind"] not in ("other",) or triage.get("claimed_amount")
    if referencing:
        kind = triage["kind"]
        days = list(dict.fromkeys(triage["days"]))[:1]
    elif open_conv_issues:
        last = open_conv_issues[-1]
        kind = last["kind"]
        days = [last["ist_day"]] if last["ist_day"] else []
    else:
        kind, days = "other", []

    # ---- stage: verify (traced tool calls) ----
    facts: dict = {"day": days[0] if days else None, "day_details": {},
                   "trip_shortfalls": {}, "incentive_gap": False}
    trip_ids = []
    foreign = None
    for tid in triage["trip_ids"]:
        info = tools.lookup_trip(conn, rider_id, tid, received_at)
        if info.get("owned_by_rider") is False:
            foreign = info
            break
        if info.get("owned_by_rider"):
            trip_ids.append(tid)
    if foreign:
        _record_ops(conn, rider_id, "escalation", None,
                    f"{rider_id} disputes trip {foreign['trip_id']} owned by {foreign['owner']}")
        return _finish(conn, rider_id, message_id, replies.identity_bound(),
                       "NOT_RIDERS_TRIP", f"foreign trip {foreign['trip_id']}")

    out_of_window = [d for d in days
                     if not _window_ok(conn, rider_id, d, received_at)]
    if out_of_window and not trip_ids:
        reply = replies.out_of_window(out_of_window[0])
        issue_id = issues.upsert_issue(conn, convo["conversation_id"], rider_id, kind,
                                       out_of_window[0], [], triage.get("claimed_amount"), [])
        issues.set_outcome(conn, issue_id, "OUT_OF_WINDOW", "resolved")
        _record_ops(conn, rider_id, "escalation", None,
                    f"out-of-window dispute {issue_id} (informational)")
        return _finish(conn, rider_id, message_id, reply, "OUT_OF_WINDOW", issue_id)

    # day-based claims: incentive check + shortfall verify
    for day in days or ([last_day_of_open(open_conv_issues)] if not referencing else []):
        _day_facts(conn, rider_id, day, received_at, facts)

    if trip_ids or (days and triage["kind"] != "incentive"):
        inc_days = _incentive_days(conn, rider_id, days) if triage["kind"] == "incentive" else {}
        verdict = tools.verify(conn, rider_id, trip_ids, _effective_days(days, inc_days),
                               received_at)
    elif days:  # incentive only
        verdict = tools.verify(conn, rider_id, [], days, received_at)
    else:
        verdict = None

    # merge verdict into facts for reply validation/templates
    if verdict:
        facts["verified_amount"] = verdict.verified_amount
        facts["route"] = verdict.route
        facts["route_reason"] = verdict.route_reason
        for key, val in verdict.shortfalls.items():
            if key.startswith("incentive:"):
                facts["incentive_shortfall"] = int(val)
            else:
                facts["trip_shortfalls"][key] = int(val)
        if triage["kind"] == "incentive" and days:
            facts["incentive_gap"] = not verdict.shortfalls.get(f"incentive:{days[0]}")

    # ---- stage: route decision ----
    outcome = _decide_outcome(conn, triage, trip_ids, days, verdict,
                              open_conv_issues if not referencing else [], facts)

    # ---- stage: act (money / approval / ask / explain) ----
    issue_id = issues.upsert_issue(conn, convo["conversation_id"], rider_id, kind,
                                   days[0] if days else None, trip_ids,
                                   triage.get("claimed_amount"), [])
    reply = _act(conn, rider_id, message_id, outcome, verdict, facts, triage,
                 issue_id, days, received_day, conversation=convo)
    trace(conn, rider_id, "decision", "outcome", {"issue_id": issue_id},
          {"outcome": outcome, "kind": kind, "days": days, "trips": trip_ids})
    return _finish(conn, rider_id, message_id, reply, outcome, issue_id)


# ---------------- stages ----------------


def _day_facts(conn, rider_id: str, day: str, received_at: str, facts: dict) -> None:
    rows = tools.list_rider_trips(conn, rider_id, day, received_at)
    completed = [r for r in rows if r["status"] == "completed"]
    expected = sum(Decimal(r["expected"]) for r in completed)
    paid = sum(Decimal(r["paid"]) for r in rows)
    facts["day_details"][day] = {
        "completed": len(completed), "expected": expected, "paid": paid,
        "gap": max(Decimal(0), expected - paid),
        "trip_ids": [r["trip_id"] for r in rows],
    }


def _incentive_days(conn, rider_id: str, days: list[str]) -> dict[str, int]:
    if not days:
        return {}
    from app.policy import trip_ist_day

    rows = conn.execute(
        "SELECT trip_id, status, started_at FROM trips WHERE rider_id = %s", [rider_id]
    ).fetchall()
    counts: dict[str, int] = {}
    for row in rows:
        d = trip_ist_day(_retrip(row)).isoformat()
        counts[d] = counts.get(d, 0) + 1
    return {d: counts.get(d, 0) for d in days if counts.get(d, 0) >= 12}


def _retrip(row) -> object:
    from app.policy import TripRecord

    return TripRecord(trip_id=row["trip_id"], rider_id="", status=row["status"],
                      started_at=row["started_at"].isoformat(), distance_km=None,
                      surge_multiplier=None) if False else type("T", (), {
                          "trip_id": row["trip_id"], "status": row["status"]})()


def _effective_days(days: list[str], inc_days: dict) -> list[str]:
    return days


def _window_ok(conn, rider_id: str, day: str, received_at: str) -> bool:
    from app.policy import within_window

    return within_window(received_at, datetime.date.fromisoformat(day))


def last_day_of_open(open_issues: list[dict]) -> str | None:
    for issue in reversed(open_issues):
        if issue.get("ist_day"):
            return issue["ist_day"]
    return None


def _decide_outcome(conn, triage, trip_ids, days, verdict, open_issues, facts) -> str:
    if triage.get("asks_human"):
        return "ESCALATE"
    if not trip_ids and not days and verdict is None:
        # vague complaint: ask once, then route to approval-like escalation
        return "NEED_INFO"
    if verdict is None:
        return "NEED_INFO"
    if verdict.state == "unknown_rider":
        return "ESCALATE"
    if verdict.state == "cannot_verify":
        return "NEED_INFO"
    if verdict.state == "verified" and verdict.verified_amount > 0:
        return "PAY-DECIDED"
    if verdict.state == "no_shortfall":
        if triage.get("claimed_amount") and facts["trip_shortfalls"]:
            return "PAY-DECIDED"  # partial shortfall evidence exists
        return "NO_DISPUTE_EXPLAIN"
    if verdict.state == "verified":  # amount 0
        return "NO_DISPUTE_EXPLAIN"
    return "NEED_INFO"


def _act(conn, rider_id, message_id, outcome, verdict, facts, triage, issue_id, days,
         received_day, conversation) -> str:
    if outcome == "PAY-DECIDED" and verdict:
        amount = int(verdict.verified_amount)
        dispute_id = deterministic_dispute_id(rider_id, triage["kind"], days)
        from app.payments import list_for_rider_day, send_payout

        caps_paid = list_for_rider_day(conn, rider_id, received_day.isoformat())
        pending = [p for p in caps_paid if p["state"] in ("intent", "sent", "confirmed")]
        if verdict.route == "auto" and not pending:
            client = PaySwiftClient(base_url=settings.payswift_base_url)
            result = send_payout(conn, client, rider_id, dispute_id, amount, "auto",
                                 idempotency_key(dispute_id, rider_id, amount, "auto"))
            if result["state"] == "confirmed":
                trace(conn, rider_id, "decision", "payout_sent",
                      {"dispute_id": dispute_id, "amount": amount}, result)
                issues.set_outcome(conn, issue_id, "PAY", "resolved")
                return replies.pay_confirmed(amount, "auto", facts)
            trace(conn, rider_id, "decision", "payout_pending",
                  {"dispute_id": dispute_id, "amount": amount}, result)
            ops_id = _record_ops(conn, rider_id, "approval", amount,
                                 f"payout {result['state']}: "
                                 f"{(result.get('error') or '')[:120]}", dispute_id)
            issues.set_outcome(conn, issue_id, "PAY", "pending_approval")
            return replies.approval_logged(amount, "payment in flight, ops ke paas", facts)
        reason = verdict.route_reason or "routes outside auto at the moment"
        _record_ops(conn, rider_id, "approval", amount, reason, dispute_id)
        trace(conn, rider_id, "decision", "approval_logged",
              {"dispute_id": dispute_id, "amount": amount},
              {"reason": reason, "route": verdict.route})
        issues.set_outcome(conn, issue_id, "PAY", "pending_approval")
        return replies.approval_logged(amount, reason, facts)

    if outcome == "ALREADY_PAID" or outcome == "NO_DISPUTE_EXPLAIN":
        reply = _explain(conn, triage, facts, days)
        issues.set_outcome(conn, issue_id, "NO_DISPUTE_EXPLAIN", "resolved")
        return reply

    if outcome == "OUT_OF_WINDOW":
        return replies.out_of_window(days[0] if days else "")

    if outcome == "NEED_INFO":
        asks = issues.ask_count_of(conn, issue_id)
        if asks < 1:
            issues.increment_ask(conn, issue_id)
            trace(conn, rider_id, "decision", "need_info", {"issue_id": issue_id},
                  {"ask": asks + 1, "policy": "one clarifying ask, then route out"})
            return replies.need_info(True)
        _record_ops(conn, rider_id, "escalation", None,
                    "unverifiable: clarification beyond first ask")
        trace(conn, rider_id, "decision", "escalate", {"issue_id": issue_id},
              {"reason": "clarify limit"})
        issues.set_outcome(conn, issue_id, "ESC", "open")
        return replies.escalation("unverifiable")

    if outcome == "ESCALATE":
        _record_ops(conn, rider_id, "escalation", None,
                    triage.get("tone_flag") or triage.get("kind") or "rider asked human")
        issues.set_outcome(conn, issue_id, "ESC", "open")
        return replies.escalation("human")

    return replies.escalation("fallback")


def _explain(conn, triage, facts, days) -> str:
    day = days[0] if days else None
    if triage["kind"] == "incentive" and day:
